        r0 = dm(i2, 1);
    .bqiSB_MOUT_OEQ_03_04: dm(i1, 1) = r0;
    r0 = 0;
    dm(_bqi_lat_MOUT_OEQ_03_04) = r0;

.bqiN_MOUT_OEQ_03_04:
    /* scalar fallback: the two nodes, unchanged */
    call _C2_MAIN_OEQ_03_process;
    call _C2_MAIN_OEQ_04_process;
    rts;
_C2BQP_MOUT_OEQ_03_04_process.end:

